import {readCart,writeCart,fetchQuote,kroner,escape} from './pf-cart.mjs';
import {loadFile} from './storage.mjs';

const get=async url=>{const response=await fetch(url);if(!response.ok)throw Error('Oplysningerne kunne ikke hentes.');return response.json();};
export function checkoutPage(){return `<section class="wrap section pf-checkout"><p class="eyebrow">SIKKER BETALING</p><h1>Levering og betaling</h1><p>Vi låser prisen, når du går videre til den sikre betalingsside. Du kan bruge MobilePay eller kort, herunder Apple Pay på understøttede enheder.</p><p><strong>Beløbet reserveres nu, men hæves først, når Smerch har godkendt PF Concepts korrektur.</strong> Hvis reservationen udløber inden da, beder vi dig godkende betalingen igen.</p><div class="cart-layout"><form id="pf-checkout-form"><h2>Leveringsadresse</h2><div class="form-grid"><label>Navn *<input name="name" autocomplete="name" required maxlength="200"></label><label>E-mail *<input name="email" type="email" autocomplete="email" required maxlength="254"></label><label>Telefon *<input name="phone" type="tel" autocomplete="tel" required maxlength="40"></label><label>Virksomhed<input name="company" autocomplete="organization" maxlength="200"></label><label>Adresse *<input name="street" autocomplete="street-address" required maxlength="200"></label><label>Postnummer *<input name="postalCode" autocomplete="postal-code" inputmode="numeric" pattern="[0-9]{4}" required maxlength="4"></label><label>By *<input name="city" autocomplete="address-level2" required maxlength="200"></label><label>Land<input value="Danmark" readonly><input type="hidden" name="country" value="DK"></label></div><p class="error" id="pf-checkout-error" role="alert"></p><button class="button wide" type="submit" disabled>Reservér beløbet sikkert ↗</button><p class="small muted">Du modtager en ordrestatus, når reservationen er bekræftet.</p></form><aside class="cart-summary"><h2>Din ordre</h2><div id="pf-checkout-summary" aria-live="polite">Beregner pris…</div><a class="text-link" href="/kurv">Ret kurven</a></aside></div></section>`;}
export function orderPage(){const id=new URLSearchParams(location.search).get('checkout')||'';return `<section class="wrap section pf-checkout"><p class="eyebrow">DIN ORDRE</p><h1>Ordrestatus</h1><div class="review-complete"><p id="pf-order-status" aria-live="polite">Kontrollerer reservationen…</p><div id="pf-order-tracking"></div><button type="button" id="pf-reauthorize" class="button" hidden>Godkend betalingen igen</button>${id?`<p class="small muted">Ordreference: ${escape(id)}</p>`:''}<a class="text-link" href="/produkter">Tilbage til produkterne</a></div></section>`;}
export async function bindCheckout(notify){
 const form=document.querySelector('#pf-checkout-form');if(form){const button=form.querySelector('button[type=submit]'),summary=document.querySelector('#pf-checkout-summary'),error=document.querySelector('#pf-checkout-error'),lines=readCart();
  if(!lines.length){summary.textContent='Kurven er tom.';return;}
  try{const [quote,config,fulfillment]=await Promise.all([fetchQuote(lines),get('/api/checkout/status'),fetch('/api/checkout/fulfillment',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lines})}).then(response=>{if(!response.ok)throw Error('Forsendelserne kunne ikke vurderes.');return response.json();})]);if(!document.contains(form))return;
   if(quote.totalIncVat===null){summary.innerHTML=`<p class="error">${escape(quote.message||'Prisen mangler.')}</p>`;return;}
   const freightExVat=fulfillment.ready?fulfillment.groups.reduce((sum,group)=>sum+(config.freightByLocation?.[group.location]??(fulfillment.groups.length===1?config.freightExVat:0)),0):null,freightIncVat=freightExVat===null?null:freightExVat+Math.round(freightExVat*.25);summary.innerHTML=`<dl class="pf-price-breakdown"><div><dt>Varer og tryk inkl. moms</dt><dd>${kroner(quote.totalIncVat)}</dd></div><div><dt>Fragt inkl. moms</dt><dd>${freightIncVat!==null?kroner(freightIncVat):'Afventer'}</dd></div><div class="pf-price-total"><dt>I alt inkl. moms</dt><dd>${freightIncVat!==null?kroner(quote.totalIncVat+freightIncVat):'Afventer'}</dd></div></dl><p class="small muted">${fulfillment.groups.map(group=>`${group.location==='PL'?'Polen':group.location==='UK'?'Storbritannien':escape(group.location)}: ${group.lineIndexes.length} varelinje${group.lineIndexes.length===1?'':'r'}`).join(' · ')}${fulfillment.unknownLineIndexes.length?` · ${fulfillment.unknownLineIndexes.length} uafklaret`:''}</p>`;
   if(!fulfillment.ready){error.textContent=fulfillment.message;return;}
   if(!config.ready){error.textContent=`Betaling er endnu ikke åben: ${config.reason}`;return;}button.disabled=false;
  }catch(e){error.textContent=e.message;return;}
  form.onsubmit=async event=>{event.preventDefault();if(!form.reportValidity())return;button.disabled=true;error.textContent='';button.textContent='Forbereder betaling…';
   try{const lines=readCart(),ids=[...new Set(lines.flatMap(line=>line.decorations.flatMap(deco=>(deco.artworks||[]).map(art=>art.logo.id))))],artworks=[];
    for(const id of ids){const blob=await loadFile(id);if(!blob)throw Error('En logofil mangler i browseren. Åbn produktet og upload den igen.');const bytes=new Uint8Array(await blob.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));artworks.push({id,base64:btoa(binary)});}
    const shipping=Object.fromEntries(new FormData(form)),response=await fetch('/api/checkout/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({lines,shipping,artworks})}),result=await response.json();if(!response.ok)throw Error(result.error||'Betalingen kunne ikke startes.');sessionStorage.setItem('pf-checkout-id',result.id);sessionStorage.setItem('pf-checkout-cart',JSON.stringify(lines));location.assign(result.url);
   }catch(e){error.textContent=e.message;button.disabled=false;button.textContent='Reservér beløbet sikkert ↗';notify?.(e.message);}
  };
 }
 const status=document.querySelector('#pf-order-status');if(status){const id=new URLSearchParams(location.search).get('checkout');if(!/^pay-[a-f0-9-]{36}$/.test(id||'')){status.textContent='Betalingsreferencen mangler.';return;}
  const retry=document.querySelector('#pf-reauthorize'),tracking=document.querySelector('#pf-order-tracking');retry.onclick=async()=>{retry.disabled=true;try{const response=await fetch(`/api/checkout/${encodeURIComponent(id)}/reauthorize`,{method:'POST'}),result=await response.json();if(!response.ok)throw Error(result.error||'Betalingen kunne ikke startes igen.');location.assign(result.url);}catch(error){status.textContent=error.message;retry.disabled=false;}};
  const refresh=async()=>{try{const order=await get(`/api/checkout/${encodeURIComponent(id)}`);if(!document.contains(status))return;retry.hidden=!['authorization_expired','expired','payment_failed'].includes(order.status);if(['authorized','capture_reconciliation','paid'].includes(order.status)&&sessionStorage.getItem('pf-checkout-id')===id&&sessionStorage.getItem('pf-checkout-cart')===JSON.stringify(readCart()))writeCart([]);if(order.status==='authorized')status.innerHTML=`<strong>${kroner(order.totalIncVat)} er reserveret, men ikke hævet.</strong><br>Vi afventer PF Concepts korrektur og Smerchs godkendelse.${order.authorizationExpiresAt?` Reservationen udløber ${new Date(order.authorizationExpiresAt).toLocaleString('da-DK')}.`:''}`;else if(order.status==='capture_reconciliation')status.textContent='Godkendelsen er registreret. Vi afstemmer hævningen hos betalingsudbyderen.';else if(order.status==='paid'){const pf=order.pfOrders||[],released=pf.length>0&&pf.every(row=>['approval_recorded','processing','shipped'].includes(row.status));status.innerHTML=`<strong>Betalingen på ${kroner(order.totalIncVat)} er hævet.</strong><br>${released?'PF Concept har kvitteret for korrekturgodkendelsen.':'Produktionen afventer PF Concepts kvittering på korrekturgodkendelsen.'}`;}else if(order.status==='authorization_expired')status.textContent='Reservationen er udløbet. Godkend betalingen igen, så ordren kan fortsætte.';else if(order.status==='expired')status.textContent='Betalingslinket er udløbet. Godkend betalingen igen.';else if(order.status==='payment_failed')status.textContent='Betalingen lykkedes ikke. Prøv at godkende den igen.';else status.textContent='Vi afventer bekræftelse på reservationen. Siden opdateres automatisk.';tracking.replaceChildren();for(const pf of order.pfOrders||[]){if(pf.status==='shipped'){const p=document.createElement('p');p.textContent=`Afsendt${pf.carrier?' med '+pf.carrier:''}. Tracking: ${Array.isArray(pf.tracking)?pf.tracking.join(', '):String(pf.tracking||'Afventer')}`;tracking.append(p);}}if(['authorized','capture_reconciliation','paid','awaiting_payment'].includes(order.status))setTimeout(refresh,5000);}catch{status.textContent='Ordrestatus kunne ikke hentes. Genindlæs siden om lidt.';}};refresh();
 }
}
